sys_script_include.script:
var DeskMateUtils = Class.create();
DeskMateUtils.prototype = {
    initialize: function () {},

    extractKeywords: function (text) {
        if (!text) return [];
        var stopWords = [
            'the', 'a', 'an', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
            'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'could',
            'should', 'may', 'might', 'can', 'shall', 'to', 'of', 'in', 'for',
            'on', 'with', 'at', 'by', 'from', 'as', 'into', 'through', 'during',
            'before', 'after', 'above', 'below', 'between', 'out', 'off', 'over',
            'under', 'again', 'further', 'then', 'once', 'here', 'there', 'when',
            'where', 'why', 'how', 'all', 'each', 'every', 'both', 'few', 'more',
            'most', 'other', 'some', 'such', 'no', 'nor', 'not', 'only', 'own',
            'same', 'so', 'than', 'too', 'very', 'just', 'because', 'but', 'and',
            'or', 'if', 'while', 'about', 'up', 'this', 'that', 'these', 'those',
            'it', 'its', 'i', 'me', 'my', 'we', 'our', 'you', 'your', 'he', 'him',
            'his', 'she', 'her', 'they', 'them', 'their', 'what', 'which', 'who',
            'whom', 'been', 'also', 'any', 'get', 'got', 'like', 'need', 'new',
            'now', 'one', 'see', 'use', 'way', 'per', 'via'
        ];

        var words = text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/);
        var keywords = [];
        for (var i = 0; i < words.length; i++) {
            var word = words[i].trim();
            if (word.length > 2 && stopWords.indexOf(word) === -1) {
                if (keywords.indexOf(word) === -1) {
                    keywords.push(word);
                }
            }
        }
        return keywords;
    },

    truncateText: function (text, maxLength) {
        if (!text) return '';
        if (text.length <= maxLength) return text;
        return text.substring(0, maxLength);
    },

    logInfo: function (message) {
        gs.info('[DeskMate] ' + message);
    },

    logError: function (message) {
        gs.error('[DeskMate] ' + message);
    },

    type: 'DeskMateUtils',
};
